// spec: specs/orders.md §36 · кейс .qa/tests/orders/ord-49 · seed: tests/seed.admin.spec.ts (+ test.use на роль)
// #5e97b8 (запрос клиента 17.11): при «אשר הזמנה» заказа с сайта клиентов создаётся קבלה (מסמך פנימי — אינו מהווה חשבונית מס) — видна в заказе и
//   в карточке клиента. Данные: заказ #685 (клиент «test», מצית קליפט ×1 ₪4.00, קבלה #2; לפני מע"מ ₪3.39, מע"מ 18% ₪0.61).
//   Печать (реджект e842179): ח.פ. / עוסק 32134455 и «תאריך הזמנה» 18.11.2026 — под своими заголовками (правые края значения и заголовка равны).
// Не дублирует ord-46 (тексты /receipt без קבלה), ord-47 (URL по номеру), dlv-19 (шапка .pd-meta), auth-19 (повторный approve).
// Чтение — @prod-safe. Блок «קבלה» в карточке заказа и список «קבלות» у клиента появляются после загрузки — ждём, не считаем отсутствием.
// Сценарий «новый заказ → אשר הזמנה» — @data (создаёт неудаляемый заказ QA-AUTO-, 1 × ₪5.00).
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { buyerPlaceOrder, openOrder, header, cleanup } from './_qa-order';

const auth = (id: string) => path.resolve(__dirname, '../../../auth', `${id}.json`);
const UUID_685 = 'a6f2f8c0-6d4d-4a8b-a03f-44f041778a3d';
const CUSTOMER_TEST = 'a30f4767-3f86-4a49-a441-ecfd2faad6d0';
const NOT_AN_INVOICE = 'מסמך פנימי — אינו מהווה חשבונית מס';
const ITEM = { id: '340b7b2b-e022-4f3b-a6f0-f9a3dc8ecfe8', name: 'מצית קליפט' }; // ₪5.00 у клиента test

/** Блок «קבלה» в карточке заказа: ждём «הופקה אוטומטית באישור ההזמנה» (грузится позже остальной карточки). */
async function receiptCard(page: Page) {
  const main = page.getByRole('main');
  const stamp = main.getByText(/הופקה אוטומטית באישור ההזמנה/);
  await expect(stamp).toBeVisible({ timeout: 30_000 });
  return { main, stamp };
}

test.describe('admin — קבלה #2 של הזמנה #685 (קריאה בלבד)', () => {
  test.use({ storageState: auth('admin') });

  test('כרטיס «קבלה» בהזמנה #685: «קבלה #2», ₪4.00, «הופקה אוטומטית באישור ההזמנה», «מסמך פנימי…», «צפייה» ו«הדפסה / PDF» #5e97b8 @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/orders/${UUID_685}`);
    await expect(page.getByRole('heading', { level: 1, name: 'הזמנה #685' })).toBeVisible({ timeout: 30_000 });
    const { main } = await receiptCard(page);
    await expect(main.getByText('קבלה #2', { exact: true })).toBeVisible();
    await expect(main.getByText(NOT_AN_INVOICE, { exact: true })).toBeVisible();
    await expect(main.getByRole('button', { name: 'צפייה', exact: true })).toBeVisible();
    await expect(main.getByRole('button', { name: 'הדפסה / PDF', exact: true })).toBeVisible();
    // сумма קבלה = סה"כ לתשלום заказа
    await expect(main.getByText('₪4.00', { exact: true }).first()).toBeVisible();
  });

  test('/orders/685/receipt תואם להזמנה: מספר, פריט, מחיר, מע"מ, «מסמך פנימי…» #5e97b8 @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/orders/${UUID_685}/receipt`);
    await expect(page.getByRole('heading', { level: 1, name: 'קבלה #2 · הזמנה #685' })).toBeVisible({ timeout: 30_000 });
    const main = page.getByRole('main');
    await expect(main.getByText(NOT_AN_INVOICE, { exact: true })).toBeVisible();
    await expect(main).toContainText('באנגו דלי'); // מנפיק
    await expect(main).toContainText(/לקוח\s*test/);
    await expect(main).toContainText(/ח\.פ\. \/ עוסק\s*32134455/);
    await expect(main).toContainText(/כתובת\s*פתח תקווה ריבלין 2/);
    await expect(main).toContainText(/תאריך הזמנה\s*18\.11\.2026/);
    await expect(main).toContainText('מצית קליפט');
    await expect(main).toContainText('מק"ט: 5710840209437');
    await expect(main).toContainText(/1\s*×\s*₪4\.00/);
    await expect(main).toContainText(/סה["״]כ פריטים\s*1/);
    await expect(main).toContainText(/לפני מע["״]מ\s*₪3\.39/);
    await expect(main).toContainText(/מע["״]מ 18%\s*₪0\.61/);
    await expect(main).toContainText(/סה["״]כ כולל מע["״]מ\s*₪4\.00/);

    // то же, что в заказе: «מצית קליפט», ₪4.00, סה"כ לתשלום ₪4.00
    await page.goto(`/orders/${UUID_685}`);
    await expect(page.getByRole('heading', { level: 1, name: 'הזמנה #685' })).toBeVisible({ timeout: 30_000 });
    const order = page.getByRole('main');
    await expect(order).toContainText('מצית קליפט');
    await expect(order).toContainText(/סה["״]כ לתשלום\s*₪4\.00/);
  });

  test('הדפסה: ח.פ. / עוסק 32134455 ו«תאריך הזמנה» 18.11.2026 תחת הכותרות שלהם, קצה ימני = קצה כותרת (±1px) #5e97b8 @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/orders/${UUID_685}/receipt`);
    await expect(page.getByRole('heading', { level: 1, name: 'קבלה #2 · הזמנה #685' })).toBeVisible({ timeout: 30_000 });
    await page.emulateMedia({ media: 'print' });
    await expect(page.locator('.pd-fields')).toBeVisible();
    const fields = await page.evaluate(() => {
      const strip = (s: string) => s.replace(/[‎‏‪-‮⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();
      const rg = (e: Element) => { const r = document.createRange(); r.selectNodeContents(e); return r.getBoundingClientRect(); };
      return [...document.querySelectorAll('.pd-field')]
        .filter((f) => (f as HTMLElement).checkVisibility())
        .map((f) => {
          const l = rg(f.querySelector('.pd-field-label')!), v = rg(f.querySelector('.pd-field-value')!);
          return {
            label: strip(f.querySelector('.pd-field-label')!.textContent || ''),
            value: strip(f.querySelector('.pd-field-value')!.textContent || ''),
            lr: l.right, vr: v.right, lt: l.top, vt: v.top,
          };
        });
    });
    const by = (label: string) => fields.find((f) => f.label === label)!;
    expect(fields.map((f) => f.label).sort(), 'поля шапки печати').toEqual(['ח.פ. / עוסק', 'כתובת', 'לקוח', 'תאריך הזמנה'].sort());
    expect(by('ח.פ. / עוסק').value).toBe('32134455');
    expect(by('תאריך הזמנה').value).toBe('18.11.2026');
    for (const f of fields) {
      expect(Math.abs(f.vr - f.lr), `«${f.label}»: правый край значения ${f.vr.toFixed(1)} = заголовка ${f.lr.toFixed(1)} (±1px)`).toBeLessThanOrEqual(1);
      expect(f.vt, `«${f.label}»: значение под заголовком`).toBeGreaterThan(f.lt);
    }
    // колонки: «ח.פ. / עוסק» и «תאריך הזמנה» в одной, «לקוח» и «כתובת» — в другой (правее)
    expect(Math.abs(by('ח.פ. / עוסק').lr - by('תאריך הזמנה').lr), 'ח.פ. и תאריך הזמנה — одна колонка').toBeLessThanOrEqual(1);
    expect(Math.abs(by('לקוח').lr - by('כתובת').lr), 'לקוח и כתובת — одна колонка').toBeLessThanOrEqual(1);
    expect(by('לקוח').lr, 'колонка «לקוח» правее колонки «ח.פ. / עוסק»').toBeGreaterThan(by('ח.פ. / עוסק').lr + 50);
    await expect(page.getByText(NOT_AN_INVOICE).last()).toBeVisible();
  });

  test('כרטיס לקוח «test»: בלוק «קבלות» עם «קבלה #2 · הזמנה #685», לחיצה → /receipt #5e97b8 @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/customers/${CUSTOMER_TEST}`);
    await expect(page.getByRole('heading', { name: 'קבלות', exact: true })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText('מופקות אוטומטית באישור הזמנה · ' + NOT_AN_INVOICE)).toBeVisible();
    const row = page.getByRole('button', { name: /^קבלה #2\s*הזמנה #685/ });
    await expect(row).toBeVisible({ timeout: 30_000 });
    await expect(row).toContainText('₪4.00');
    await row.click();
    await expect(page).toHaveURL(new RegExp(`/orders/${UUID_685}/receipt$`), { timeout: 30_000 });
    await expect(page.getByRole('heading', { level: 1, name: 'קבלה #2 · הזמנה #685' })).toBeVisible({ timeout: 30_000 });
  });
});

test.describe('dist2 — מפיץ שני לא רואה את הקבלה', () => {
  test.use({ storageState: auth('dist2') });

  test('dist2: /orders/685/receipt ו-/orders/<uuid #685>/receipt — «ההזמנה לא נמצאה.», בלי «קבלה #2» #5e97b8 @desktop @prod-safe', async ({ page }) => {
    for (const p of ['/orders/685/receipt', `/orders/${UUID_685}/receipt`]) {
      await page.goto(p);
      await expect(page.getByRole('main').getByText('ההזמנה לא נמצאה.', { exact: true })).toBeVisible({ timeout: 30_000 });
      await expect(page.getByRole('heading', { name: /קבלה #2/ })).toHaveCount(0);
      await expect(page.getByText('₪3.39')).toHaveCount(0);
    }
  });
});

test.describe('הזמנה חדשה → «אשר הזמנה» → בדיוק קבלה אחת', () => {
  test.use({ storageState: auth('admin') });
  test.describe.configure({ mode: 'serial' });

  let orderNo: string | undefined;
  let approved = false;

  test.afterAll(async ({ browser }) => {
    // утверждённый заказ неудаляем и не отклоняется (в «Тестовые данные для чистки»); неутверждённый — отклоняем
    if (!approved) await cleanup(browser, [orderNo], []);
  });

  test('buyer מזמין QA-AUTO (₪5.00) → אדמין «אשר הזמנה» → קבלה אחת חדשה (לא #2); רענון ו«קבלות» של הלקוח לא מכפילים #5e97b8 @desktop @data', async ({ page, browser }) => {
    test.setTimeout(240_000);
    orderNo = await buyerPlaceOrder(browser, [{ ...ITEM, qty: 1 }], `QA-AUTO-receipt-on-approve-${Date.now()}`);

    await openOrder(page, orderNo);
    await page.getByRole('button', { name: 'אישור הזמנה' }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: `אישור הזמנה #${orderNo}` })).toBeVisible();
    await dlg.getByRole('button', { name: 'אשר הזמנה' }).click();
    await expect(header(page)).toContainText('אושרה · ממתינה לליקוט', { timeout: 30_000 });
    approved = true;

    const { main, stamp } = await receiptCard(page);
    const receiptLabel = main.getByText(/^קבלה #\d+$/);
    await expect(receiptLabel, 'ровно одна קבלה у заказа').toHaveCount(1);
    const no = (await receiptLabel.innerText()).match(/#(\d+)/)![1];
    expect(no, 'номер новой קבלה не #2 (она у #685)').not.toBe('2');
    await expect(stamp).toBeVisible();
    await expect(main.getByText(NOT_AN_INVOICE, { exact: true })).toBeVisible();
    await expect(main.getByRole('button', { name: 'צפייה', exact: true })).toBeVisible();

    // refresh не создаёт вторую קבלה и не меняет номер
    await page.reload();
    await receiptCard(page);
    await expect(page.getByRole('main').getByText(/^קבלה #\d+$/)).toHaveText(`קבלה #${no}`);

    // карточка клиента «test»: одна строка этого заказа, номера קבלות уникальны
    await page.goto(`/customers/${CUSTOMER_TEST}`);
    const rows = page.getByRole('button', { name: /^קבלה #\d+\s*הזמנה #\d+/ });
    const mine = page.getByRole('button', { name: new RegExp(`^קבלה #${no}\\s*הזמנה #${orderNo} `) });
    await expect(mine).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('button', { name: new RegExp(`הזמנה #${orderNo} `) }).and(rows), 'у заказа одна строка в «קבלות»').toHaveCount(1);
    const nums = (await rows.allInnerTexts()).map((t) => t.match(/^קבלה #(\d+)/)![1]);
    expect(new Set(nums).size, `номера קבלות уникальны: ${nums.join(', ')}`).toBe(nums.length);
    await expect(mine).toContainText('₪5.00');
    await mine.click();
    await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}\/receipt$/, { timeout: 30_000 });
    await expect(page.getByRole('heading', { level: 1, name: `קבלה #${no} · הזמנה #${orderNo}` })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('main')).toContainText(/סה["״]כ כולל מע["״]מ\s*₪5\.00/);
  });
});
